INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 23, 'theory', 'Quiz: idempotent automation');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 23, 0, 'What does it mean that automation is idempotent?', '["It always runs faster than the previous run", "It writes nothing to the log", "A repeated run with the same input changes nothing, changed is zero", "It runs only once in a lifetime"]', 2, 'Idempotence is a property of the outcome: when the host is already in the desired state, a second run changes nothing and the report shows changed=0. Speed and logging are irrelevant.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 23, 1, 'Why can a script with a bare useradd deploy not be safely run again?', '["On an existing name useradd fails with status 9", "useradd creates a new user with a different name every time", "useradd deletes the home directory on the second run", "useradd works only for an ordinary user"]', 0, 'The name is taken, and man useradd lists exit status 9 for this. A script that stops on error will fail; so first check whether the user exists (id), or use a module that compares the state itself.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 23, 2, 'Two tasks of a play reported changed and both notified the handler restart nginx. How many times does it run in Ansible?', '["Twice, after each task", "Once, at the end of the play section", "Never, until restart is called by hand", "As many times as there are hosts in the inventory"]', 1, 'A handler runs once however many tasks notify it, after the tasks section (or earlier by meta: flush_handlers). The number of hosts does not multiply runs on one host.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 23, 3, 'What is true of an ansible-playbook run with --check?', '["It is guaranteed to predict all changes", "It always runs all commands but writes no log", "It replaces the idempotence check with a second run", "A module without check mode support reports nothing and does nothing, so the forecast may be incomplete"]', 3, 'Check mode is a simulation: modules that support it report what they would change, the rest are skipped. So the forecast is no guarantee, and a real second run is still needed.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 23, 4, 'A lineinfile task with a regexp found three matching lines, and none equals the wanted line. What happens?', '["All three lines are replaced", "The line is added at the end and the three old ones stay", "Only the last of the found lines is replaced", "The module returns an ambiguity error"]', 2, 'The lineinfile documentation: with several matches only the last line found is replaced. Adding at the end happens only when there is no match at all.');
